/*
 * correlationBacktester.cpp
 * -------------------------------------------------------------
 * Backtest the pair signals generated by correlationTracker.
 *
 * For each *_pair.csv in correlationResult/:
 *   - position = +1 → long A, short B  (dollar neutral)
 *   - position = -1 → short A, long  B
 *   - position =  0 → flat
 *
 * PnL is computed from the daily change of the log-ratio
 * (or equivalently from the two legs).
 *
 * Output: one equity CSV per pair + a summary CSV.
 *
 * Compile:
 *   g++ -O2 -std=c++17 correlationBacktester.cpp -o correlationBacktester
 */

#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <cmath>
#include <iomanip>
#include <filesystem>
#include <algorithm>
#include <limits>

using namespace std;
namespace fs = std::filesystem;

#ifndef NAN
#define NAN (numeric_limits<double>::quiet_NaN())
#endif

// ===================== CONFIG =====================
const string SIGNAL_DIR   = "correlationResult";
const string OUT_DIR      = "correlationResult";   // results live next to signals
const double STOP_LOSS    = 0.05;   // 5% stop on the pair spread (optional)
const double CAPITAL      = 1.0;    // start equity per pair
// ==================================================

struct Row {
    string date;
    double close_a, close_b;
    double log_ratio, zscore, corr;
    int signal, position;
    // filled by backtester
    double pnl = 0;
    double equity = 1.0;
    string exit_reason;
};

vector<string> split(const string& s, char delim = ',') {
    vector<string> t;
    string item;
    istringstream ss(s);
    while (getline(ss, item, delim)) t.push_back(item);
    return t;
}

double to_d(const string& s) {
    if (s.empty() || s == "nan" || s == "NaN") return NAN;
    try { return stod(s); } catch (...) { return NAN; }
}

bool isnan_d(double x) { return x != x; }

vector<Row> load_pair_csv(const string& path) {
    vector<Row> rows;
    ifstream fin(path);
    if (!fin) return rows;
    string line;
    getline(fin, line); // header
    while (getline(fin, line)) {
        auto t = split(line);
        if (t.size() < 8) continue;
        Row r;
        r.date      = t[0].substr(0, 10);
        r.close_a   = to_d(t[1]);
        r.close_b   = to_d(t[2]);
        r.log_ratio = to_d(t[3]);
        r.zscore    = to_d(t[4]);
        r.corr      = to_d(t[5]);
        r.signal    = (int)to_d(t[6]);
        r.position  = (int)to_d(t[7]);
        rows.push_back(r);
    }
    return rows;
}

struct TradeStats {
    string pair;
    int n_trades = 0;
    int n_wins = 0;
    double total_ret = 0;
    double final_equity = 1.0;
    double max_dd = 0;
    double avg_pnl = 0;
};

TradeStats backtest_one(const string& path) {
    auto rows = load_pair_csv(path);
    TradeStats stats;
    stats.pair = fs::path(path).stem().string();

    if (rows.size() < 10) return stats;

    double equity = CAPITAL;
    double peak = CAPITAL;
    double entry_ratio = 0;
    int    cur_pos = 0;
    vector<double> trade_pnls;

    for (size_t i = 1; i < rows.size(); ++i) {
        int prev_pos = rows[i-1].position;
        int pos      = rows[i].position;

        // daily return of the pair position
        // long ratio  (+1) profits when log(A/B) rises  → d(logA) - d(logB)
        // short ratio (-1) profits when log(A/B) falls
        double ret_a = rows[i].close_a / rows[i-1].close_a - 1.0;
        double ret_b = rows[i].close_b / rows[i-1].close_b - 1.0;

        double pair_ret = 0.0;
        if (prev_pos == 1) {            // long A, short B
            pair_ret = 0.5 * ret_a - 0.5 * ret_b;
        } else if (prev_pos == -1) {    // short A, long B
            pair_ret = -0.5 * ret_a + 0.5 * ret_b;
        }

        // optional stop-loss on open position
        if (prev_pos != 0 && cur_pos != 0) {
            double move = (rows[i].log_ratio - entry_ratio) * prev_pos;
            // move is the change in the direction we are betting
            // if we are long ratio and ratio falls a lot → loss
            double approx_pnl = prev_pos * (rows[i].log_ratio - entry_ratio);
            if (approx_pnl < -STOP_LOSS) {
                // force close
                rows[i].exit_reason = "stop_loss";
                pair_ret = -STOP_LOSS;   // approximate
                pos = 0;
                rows[i].position = 0;
            }
        }

        rows[i].pnl = pair_ret;
        equity *= (1.0 + pair_ret);
        rows[i].equity = equity;
        peak = max(peak, equity);
        double dd = (equity - peak) / peak;
        if (dd < stats.max_dd) stats.max_dd = dd;

        // detect trade open / close for statistics
        if (prev_pos == 0 && pos != 0) {
            // open
            entry_ratio = rows[i].log_ratio;
            cur_pos = pos;
        } else if (prev_pos != 0 && pos == 0) {
            // close – approximate trade pnl from equity change is already in series
            // we count a trade
            stats.n_trades++;
            // crude: use the last non-zero stretch sum
            cur_pos = 0;
        }
    }

    // final mark
    stats.final_equity = equity;
    stats.total_ret = equity - 1.0;

    // recount wins from equity path segments (simple)
    double seg_start = 1.0;
    bool in_trade = false;
    for (size_t i = 1; i < rows.size(); ++i) {
        if (!in_trade && rows[i-1].position == 0 && rows[i].position != 0) {
            in_trade = true;
            seg_start = rows[i].equity;
        } else if (in_trade && rows[i].position == 0) {
            in_trade = false;
            double trade_ret = rows[i].equity / seg_start - 1.0;
            trade_pnls.push_back(trade_ret);
            if (trade_ret > 0) stats.n_wins++;
        }
    }
    stats.n_trades = (int)trade_pnls.size();
    if (!trade_pnls.empty()) {
        double s = 0;
        for (double p : trade_pnls) s += p;
        stats.avg_pnl = s / trade_pnls.size();
    }

    // write equity file
    string out_name = OUT_DIR + "/" + stats.pair + "_equity.csv";
    ofstream fout(out_name);
    fout << fixed << setprecision(6);
    fout << "time_key,close_a,close_b,log_ratio,zscore,corr,signal,position,pnl,equity,exit_reason\n";
    for (auto& r : rows) {
        fout << r.date << ","
             << r.close_a << "," << r.close_b << ","
             << r.log_ratio << ","
             << (isnan_d(r.zscore) ? "nan" : to_string(r.zscore)) << ","
             << (isnan_d(r.corr)   ? "nan" : to_string(r.corr))   << ","
             << r.signal << "," << r.position << ","
             << r.pnl << "," << r.equity << ","
             << r.exit_reason << "\n";
    }
    fout.close();
    cout << "  " << stats.pair
         << "  equity=" << stats.final_equity
         << "  trades=" << stats.n_trades
         << "  win%=" << (stats.n_trades ? 100.0*stats.n_wins/stats.n_trades : 0)
         << "  MDD=" << stats.max_dd * 100 << "%\n";

    return stats;
}

int main() {
    cout << "=== Correlation / Pairs Backtester ===\n";
    fs::create_directories(OUT_DIR);

    vector<string> pair_files;
    if (!fs::exists(SIGNAL_DIR)) {
        cerr << "Signal directory not found: " << SIGNAL_DIR << "\n";
        cerr << "Run correlationTracker first.\n";
        return 1;
    }

    for (auto& entry : fs::directory_iterator(SIGNAL_DIR)) {
        string name = entry.path().filename().string();
        if (name.size() > 9 && name.substr(name.size()-9) == "_pair.csv") {
            pair_files.push_back(entry.path().string());
        }
    }
    sort(pair_files.begin(), pair_files.end());
    cout << "Found " << pair_files.size() << " pair signal files\n";

    vector<TradeStats> all;
    for (auto& f : pair_files) {
        all.push_back(backtest_one(f));
    }

    // summary
    string sum_path = OUT_DIR + "/pairs_summary.csv";
    ofstream s(sum_path);
    s << fixed << setprecision(6);
    s << "pair,n_trades,n_wins,win_rate,avg_trade_pnl,final_equity,total_ret,max_drawdown\n";
    for (auto& t : all) {
        double wr = t.n_trades ? (double)t.n_wins / t.n_trades : 0;
        s << t.pair << ","
          << t.n_trades << "," << t.n_wins << "," << wr << ","
          << t.avg_pnl << "," << t.final_equity << ","
          << t.total_ret << "," << t.max_dd << "\n";
    }
    s.close();
    cout << "Summary written to " << sum_path << "\n";
    return 0;
} 